<?php

namespace Wallacemartinss\FilamentIconPicker\Enums;

use Illuminate\Support\Str;

use Wallacemartinss\FilamentIconPicker\Enums\Heroicons;
use Wallacemartinss\FilamentIconPicker\Enums\Filament;
use Wallacemartinss\FilamentIconPicker\Enums\Tabler;

/**
 * Icon facade for easy access to all icon enums.
 *
 * Generated by Filament Icon Picker
 */
class IconEnums
{

    /**
     * Get an icon from Heroicons.
     */
    public static function heroicons(string $name): ?string
    {
        $caseName = self::toCaseName($name);

        foreach (Heroicons::cases() as $case) {
            if ($case->name === $caseName || str_contains(strtolower($case->name), strtolower($name))) {
                return $case->value;
            }
        }

        return null;
    }

    /**
     * Get an icon from Filament.
     */
    public static function filament(string $name): ?string
    {
        $caseName = self::toCaseName($name);

        foreach (Filament::cases() as $case) {
            if ($case->name === $caseName || str_contains(strtolower($case->name), strtolower($name))) {
                return $case->value;
            }
        }

        return null;
    }

    /**
     * Get an icon from Tabler.
     */
    public static function tabler(string $name): ?string
    {
        $caseName = self::toCaseName($name);

        foreach (Tabler::cases() as $case) {
            if ($case->name === $caseName || str_contains(strtolower($case->name), strtolower($name))) {
                return $case->value;
            }
        }

        return null;
    }

    /**
     * Convert an icon name to a valid case name.
     */
    protected static function toCaseName(string $name): string
    {
        return Str::of($name)
            ->replace(['-', '_', '.'], ' ')
            ->title()
            ->replace(' ', '')
            ->toString();
    }

    /**
     * Get all available icons from all sets.
     *
     * @return array<string, array<string, string>>
     */
    public static function all(): array
    {
        return [
            'Heroicons' => Heroicons::options(),
            'Filament' => Filament::options(),
            'Tabler' => Tabler::options(),
        ];
    }
}
